// Icon masks carry the asset version exactly as the legacy stylesheet did; without
// it a changed glyph is served from cache indefinitely. Built in Go because a
// templ <style> block is static text and cannot interpolate.
func energyIconMaskCSS(assetVersion string) string {
	names := []string{
		"house-plug",
		"house",
		"solar-panel",
		"utility-pole",
		"battery",
		"binoculars",
		"check",
		"triangle-alert",
		"info",
		"play",
		"pencil",
		"log-out",
		"circle-help",
		"shield-check",
		"workflow",
		"server-cog",
		"circle-check",
		"chevron-right",
		"chevron-down",
		"ellipsis",
		"clock-3",
		"car-front",
		"plug-zap",
		"heater",
		"fan",
		"washing-machine",
		"flame",
		"drill",
		"waves-ladder",
		"square-parking",
		"plug",
		"grip-vertical",
		"plus",
		"search",
		"x",
		"snowflake",
		"shower-head",
		"chevron-down",
	}
	var b strings.Builder
	for _, n := range names {
		b.WriteString(".energy-ui-icon-" + n + "{--energy-icon:url(\"/assets/icons/lucide/" + n + ".svg?v=" + assetVersion + "\")}")
	}
	return b.String()
}

var _ = templruntime.GeneratedTemplate
